import sys

data = list(map(int, sys.stdin.read().split()))
if len(data) < 2:
    sys.exit()

a, b = data[0], data[1]
if a > b:
    a, b = b, a

end = min(b, 9)
if a <= end:
    start = a if a % 2 == 0 else a + 1
    if start <= end:
        nums = list(range(start, end + 1, 2))
        print(' '.join(map(str, nums)))
    else:
        print()
else:
    print()

n = int(input())
if n < 2:
    print(False)
else:
    is_prime = True
    i = 2
    while i * i <= n:
        if n % i == 0:
            is_prime = False
            break
        i += 1
    print(is_prime)

