import sys

nums = list(map(int, sys.stdin.read().split()))
ones = {1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five", 6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"}

nums.sort(reverse=True)

result = []
for x in nums:
    if 1 <= x <= 9:
        result.append(ones[x])

print(''.join(result))

